import { watch, type Ref } from 'vue'
import { ElMessage } from 'element-plus'
import { useRealtime, type RealtimeTopic } from './useRealtime'

export function useRealtimeRefresh(
  refreshFn: () => Promise<void> | void,
  topics: RealtimeTopic[] = ['alerts', 'incidents', 'nodes'],
  options?: { notifyEventTypes?: string[] }
) {
  const { events } = useRealtime(topics)

  let debounceTimer: ReturnType<typeof setTimeout> | null = null

  function triggerRefresh() {
    if (debounceTimer) {
      clearTimeout(debounceTimer)
    }
    debounceTimer = setTimeout(() => {
      debounceTimer = null
      try {
        refreshFn()
      } catch {
        // 忽略刷新失败，避免弹窗轰炸
      }
    }, 500)
  }

  watch(
    events as Ref<unknown[]>,
    (newEvents, oldEvents) => {
      if (!newEvents || newEvents.length === 0) return
      const oldLen = oldEvents?.length || 0
      const incoming = newEvents.slice(0, Math.max(0, newEvents.length - oldLen))

      for (const event of incoming) {
        const e = event as { event_type: string; payload?: Record<string, unknown> }
        if (options?.notifyEventTypes?.includes(e.event_type)) {
          const message = (e.payload?.title as string) || (e.payload?.rule_name as string) || e.event_type
          ElMessage.warning(`实时事件：${message}`)
        }
      }

      triggerRefresh()
    },
    { deep: true }
  )

  return { triggerRefresh }
}
